+func missingPort(addr string, defaultPort string) (string, error) {
+	// Trim brackets from address (if they exist).
+	addr = strings.TrimPrefix(addr, "[")
+	addr = strings.TrimSuffix(addr, "]")
+
+	// Add a port if it's missing.
+	_, _, err := net.SplitHostPort(addr)
+	if err != nil {
+		// `SplitHostPort` returns an error if the address is missing a
+		// port. We are looking for this specific error.
+		if strings.Contains(err.Error(), "missing port in address") {
+			return net.JoinHostPort(addr, defaultPort), nil
+		}
+
+		// Return any other error.
+		return "", err
+	}
+
+	// The address already has a port.
+	return addr, nil
+}
