diff --git a/lib/realpath.js b/lib/realpath.js
new file mode 100644
index 0000000..fc502ec
--- /dev/null
+++ b/lib/realpath.js
@@ -0,0 +1,23 @@
+
+// wrapper around realpath-native that falls back to fs.realpath if it fails
+const realpath = require('realpath-native')
+const { realpathSync } = require('fs')
+
+// realpath-native will throw instead of calling the cb
+// if the path does not exist.
+// So, just do that, and fall back to fs.realpath, which is much slower.
+// Theoreticall, this is probably not safe, because we're statting
+// a path that could change out from under us.  However, we are checking
+// for these sorts of things in the directory cache, so let the lesser
+// of two evils win.
+module.exports = path => {
+  try {
+    return realpath.sync(path)
+  } catch (er) {
+    try {
+      return realpathSync(path)
+    } catch (er) {
+      return
+    }
+  }
+}

