+// isCrossesBoundary checks if a file path is trying to escape the root directory using symlinks.
+func (fs *Filesystem) isCrossesBoundary(p string) (bool, error) {
+	// Let's check if the path is a symlink.
+	if st, err := os.Lstat(p); err != nil {
+		// If the file doesn't exist, we can't check it.
+		if os.IsNotExist(err) {
+			return false, nil
+		}
+		// An error other than the file not existing should be returned.
+		return false, err
+	} else if st.Mode()&os.ModeSymlink == 0 {
+		// If it's not a symlink, we don't need to do anything.
+		return false, nil
+	}
+
+	// Now, let's get the absolute path of the symlink's target.
+	realP, err := filepath.EvalSymlinks(p)
+	if err != nil {
+		// If the file doesn't exist, we can't check it.
+		if os.IsNotExist(err) {
+			return false, nil
+		}
+		// An error other than the file not existing should be returned.
+		return false, err
+	}
+
+	// Finally, let's check if the target path is inside the root directory.
+	if !strings.HasPrefix(realP, fs.root) {
+		return true, nil
+	}
+	return false, nil
+}
+
+// IsSameFile checks if two paths are the same file.
+func (fs *Filesystem) IsSameFile(p1, p2 string) (bool, error) {
+	st1, err := os.Stat(p1)
+	if err != nil {
+		return false, err
+	}
+	st2, err := os.Stat(p2)
+	if err != nil {
+		return false, err
+	}
+	return os.SameFile(st1, st2), nil
+}
